  border: 1px solid var(--line);
}

.editorial--feature {
  min-height: 100%;
  background:
    linear-gradient(135deg, rgba(159, 122, 234, 0.16), rgba(255, 255, 255, 0.02)),
    var(--bg-elevated);
}

.text-link {
  display: inline-flex;
  margin-top: 8px;
  font-weight: 600;
}

.site-footer {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 18px 8px 0;
  color: var(--muted);
}

@media (max-width: 1080px) {
  .product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .deal-grid,
  .editorial-layout,
  .hero {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .page-shell {
    width: min(100% - 20px, 1180px);
    padding-top: 14px;
  }

  .site-header,
  .section,
  .hero {
    padding: 22px;
    border-radius: 22px;
  }

  .site-header,
  .section-heading,
  .site-footer {
    flex-direction: column;
    align-items: flex-start;
  }

  .site-nav {
    flex-wrap: wrap;
    gap: 12px 18px;
  }

  .hero h1 {
    max-width: 100%;
  }

  .hero-metrics,
  .product-grid,
  .deal-grid {
    grid-template-columns: 1fr;
  }
}
