+const featuredProducts = [
+  {
+    name: "Obsidian Lounge Chair",
+    category: "Furniture",
+    price: "$640",
+    description: "Low-profile comfort in matte black with brushed steel framing."
+  },
+  {
+    name: "Halo Table Lamp",
+    category: "Lighting",
+    price: "$180",
+    description: "A warm ambient glow with smoked glass and a sculpted silhouette."
+  },
+  {
+    name: "Slate Serve Set",
+    category: "Dining",
+    price: "$95",
+    description: "Minimal table essentials finished with a soft stone texture."
+  },
+  {
+    name: "Velvet Throw",
+    category: "Textiles",
+    price: "$72",
+    description: "Deep charcoal layers that add softness and contrast to modern spaces."
+  }
+];
+
+const deals = [
+  {
+    title: "Studio Shelf",
+    tag: "Save 25%",
+    price: "$210",
+    originalPrice: "$280",
+    copy: "Architectural storage in powder-coated black with hidden mounting."
+  },
+  {
+    title: "Mirror Tray",
+    tag: "Bundle offer",
+    price: "$58",
+    originalPrice: "$84",
+    copy: "Reflective serving tray with a smoked finish and slim raised edges."
+  },
+  {
+    title: "Accent Pouf",
+    tag: "Ends tonight",
+    price: "$134",
+    originalPrice: "$179",
+    copy: "Compact textured seating that brings softness to darker rooms."
+  }
+];
+
+const productGrid = document.querySelector("#product-grid");
+const dealGrid = document.querySelector("#deal-grid");
+const countdownElement = document.querySelector("#countdown");
+const yearElement = document.querySelector("#current-year");
+
+function renderProducts() {
+  productGrid.innerHTML = featuredProducts
+    .map(
+      (product, index) => `
+        <article class="product-card">
+          <div class="product-card__media" aria-hidden="true">
+            <div class="product-card__glow"></div>
+            <div class="product-card__shape" style="transform: rotate(${index % 2 === 0 ? "-3deg" : "3deg"});"></div>
+          </div>
+          <div class="product-card__content">
+            <p class="meta-row">${product.category}</p>
+            <h3>${product.name}</h3>
+            <p class="product-card__description">${product.description}</p>
+          </div>
+          <div class="product-card__footer">
+            <div class="price-row">
+              <strong>${product.price}</strong>
+            </div>
+            <button class="pill-button" type="button">Add to cart</button>
+          </div>
+        </article>
+      `
+    )
+    .join("");
+}
+
+function renderDeals() {
+  dealGrid.innerHTML = deals
+    .map(
+      (deal, index) => `
+        <article class="deal-card">
+          <span class="deal-card__badge">${deal.tag}</span>
+          <div class="deal-card__media" aria-hidden="true">
+            <div class="deal-card__glow"></div>
+            <div class="deal-card__shape" style="transform: rotate(${index === 1 ? "-5deg" : "4deg"});"></div>
+          </div>
+          <div>
+            <h3>${deal.title}</h3>
+            <p class="deal-card__copy">${deal.copy}</p>
+          </div>
+          <div class="deal-card__footer">
+            <div class="deal-card__price">
+              <strong>${deal.price}</strong>
+              <span>${deal.originalPrice}</span>
+            </div>
+            <button class="pill-button pill-button--accent" type="button">Claim deal</button>
+          </div>
+        </article>
+      `
+    )
+    .join("");
+}
+
+function updateCountdown() {
+  const now = new Date();
+  const nextMidnight = new Date();
+  nextMidnight.setHours(24, 0, 0, 0);
+
+  const diff = nextMidnight - now;
+  const hours = String(Math.floor(diff / (1000 * 60 * 60))).padStart(2, "0");
+  const minutes = String(Math.floor((diff / (1000 * 60)) % 60)).padStart(2, "0");
+  const seconds = String(Math.floor((diff / 1000) % 60)).padStart(2, "0");
+
+  countdownElement.textContent = `${hours}:${minutes}:${seconds}`;
+}
+
+renderProducts();
+renderDeals();
+updateCountdown();
+
+if (yearElement) {
+  yearElement.textContent = new Date().getFullYear();
+}
+
+setInterval(updateCountdown, 1000);
+

')

